using Archipelago.MultiClient.Net.Models;
using RhythmCastleAP;
using Archipelago.MultiClient.Net.Packets;
using Newtonsoft.Json.Linq;
int checks=0;void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
Dictionary<string,object> Data(int size=2){var map=new Dictionary<string,string[]>();for(int n=0;n<30/size;n++)map[$"Cassette Bundle {n+1:00}"]=CassetteCatalog.All.Skip(n*size).Take(size).Select(c=>c.ItemName).ToArray();return new(){["schema_version"]=20,["cassette_bundle_size"]=size,["cassette_bundles"]=map};}
void Reject(Action<Dictionary<string,object>> mutate){var data=Data();mutate(data);bool rejected=false;try{CassetteBundleContract.Parse(data);}catch(InvalidOperationException){rejected=true;}Check(rejected,"malformed contract fails closed");}
Check(!CassetteBundleContract.Parse(new(){["schema_version"]=19}).Bundled,"legacy schema19 continues");
var schema21=Data();schema21["schema_version"]=21;
Check(CassetteBundleContract.Parse(schema21).SongsFor(187256164).Count==2,"schema21 pairs expand existing permanent IDs");
schema21=Data(3);schema21["schema_version"]=21;Check(CassetteBundleContract.Parse(schema21).SongsFor(187256164).Count==3,"schema21 triples");
schema21=new(){["schema_version"]=21,["cassette_bundle_size"]=1,["cassette_bundles"]=new Dictionary<string,string[]>()};Check(!CassetteBundleContract.Parse(schema21).Bundled,"schema21 individual mode");
var pairs=CassetteBundleContract.Parse(Data());Check(pairs.SongsFor(187256164).SequenceEqual(new[]{"THE_LITTLE_THINGS","NO_PLAN_B"}),"first permanent bundle expands to two actual songs");
Check(pairs.SongsFor(187256178).Count==2&&pairs.SongsFor(187256179).Count==0,"reserved ID bounds");
Check(CassetteBundleContract.Parse(Data(3)).SongsFor(187256173).Count==3&&CassetteBundleContract.Parse(Data(3)).SongsFor(187256174).Count==0,"triples have ten bundles");
Check(pairs.Display("Cassette Bundle 01").Contains("The Little Things, No Plan B"),"popup/history name identifies contents");
Reject(d=>d.Remove("cassette_bundles"));Reject(d=>d["cassette_bundle_size"]="2");Reject(d=>d["cassette_bundle_size"]=1);Reject(d=>d["schema_version"]=19);
Reject(d=>((Dictionary<string,string[]>)d["cassette_bundles"]).Remove("Cassette Bundle 15"));
Reject(d=>((Dictionary<string,string[]>)d["cassette_bundles"])["Cassette Bundle 02"][0]="The Little Things Cassette");
Reject(d=>((Dictionary<string,string[]>)d["cassette_bundles"])["Cassette Bundle 02"][0]="Unknown Cassette");
ReceivedItemsPacket Packet(int index,params long[] ids)=>new(){Index=index,Items=ids.Select(id=>new NetworkItem{Item=id}).ToArray()};
string[] Owned(){string[] result=Array.Empty<string>();CassetteBundleSessionHistory.WithSongs((managed,songs)=>result=songs.ToArray());return result;}
var history=new CassetteBundleSessionHistory(1);history.HandlePacket(Packet(0,187256164));Check(Owned().Length==0,"prelogin cannot authorize");history.Configure(Data());Check(Owned().Length==2,"authenticated history expands bundle");history.HandlePacket(Packet(0,187256164));Check(Owned().Length==2,"full replay idempotent");history.HandlePacket(Packet(1,187256165));Check(Owned().Length==4,"contiguous live receipt");history.HandlePacket(Packet(1,187256165));Check(Owned().Length==4,"identical overlapping replay idempotent");history.HandlePacket(Packet(1,187256166));Check(Owned().Length==0,"conflicting replay fails closed");history.HandlePacket(Packet(0,187256164));Check(Owned().Length==2,"full history recovers");history.HandlePacket(Packet(5,187256165));Check(Owned().Length==0,"gap fails closed");
var next=new CassetteBundleSessionHistory(2);next.Configure(Data(3));history.HandlePacket(Packet(0,187256178));Check(Owned().Length==0,"old session cannot replace new authority");next.HandlePacket(Packet(0,187256164));Check(Owned().Length==3,"new mapping replaces old mapping");CassetteBundleSessionHistory.End(2);Check(Owned().Length==0,"session end clears authorization");
var switched=new CassetteBundleSessionHistory(3);switched.Configure(Data());switched.HandlePacket(Packet(0,187256164));switched.Configure(Data(3));Check(Owned().Length==0,"map change requires fresh authenticated history");switched.HandlePacket(Packet(0,187256164));Check(Owned().Length==3,"fresh replay uses new mapping");
var starter=new CassetteBundleSessionHistory(4);starter.Configure(Data());starter.HandlePacket(Packet(0,187256151,187256164));Check(Owned().Length==3&&Owned().Contains("ZEN"),"individual starter cassette and bundle both expand from authenticated history");starter.HandlePacket(Packet(9,187256123));Check(Owned().Length==0,"gap removes individual starter and bundle authority together");starter.HandlePacket(Packet(0,187256123,187256151,187256164));Check(Owned().Length==4&&Owned().Contains("I_GOT_MONEY"),"permanent Money and Zen item IDs recover through full replay");
IReadOnlyList<string>? snapshot=null;CassetteBundleSessionHistory.WithSongs((managed,songs)=>snapshot=songs);CassetteBundleSessionHistory.WithSongs((managed,songs)=>Check(ReferenceEquals(snapshot,songs),"unchanged authenticated history reuses ownership snapshot without per-frame reconciliation"));
var legacy=new CassetteBundleSessionHistory(5);legacy.Configure(new(){["schema_version"]=19});var pendingLegacy=new CassetteBundleSessionHistory(6);CassetteBundleSessionHistory.WithSongs((managed,songs)=>Check(!managed,"legacy reconnect awaiting login cannot clear individual cassette ownership"));
int legacyCallbacks=0;var buffered=new CassetteBundleSessionHistory(7,name=>{legacyCallbacks++;return true;});Check(buffered.TryApplyItem("Zen Cassette"),"cassette name recognized before login");Check(legacyCallbacks==0,"prelogin item callbacks cannot enqueue native cassette ownership");buffered.Configure(Data());Check(legacyCallbacks==0,"bundle login discards name callbacks in favor of authenticated IDs");buffered.HandlePacket(Packet(4,187256151));buffered.TryApplyItem("Zen Cassette");Check(legacyCallbacks==0&&Owned().Length==0,"item-name callbacks cannot bypass bundle history gap");var legacyBuffered=new CassetteBundleSessionHistory(8,name=>{legacyCallbacks++;return true;});legacyBuffered.TryApplyItem("Zen Cassette");legacyBuffered.Configure(new(){["schema_version"]=19});Check(legacyCallbacks==1,"legacy login forwards buffered cassette through existing receipt path");legacyBuffered.TryApplyItem("Money Cassette");Check(legacyCallbacks==2,"legacy authenticated callbacks retain direct managed receipt behavior");
Console.WriteLine($"Cassette bundle tests passed: {checks}");
